module full_adder (
  input A,
  input B,
  input Cin,
  output reg S,
  output reg Cout
);

  always @ (A, B, Cin) begin
    S = A ^ B ^ Cin;
    Cout = (A & B) | (Cin & (A ^ B));
  end

endmodule


