  wire [4:0] sum;

  genvar i;
  generate
    for (i = 0; i < 4; i = i + 1) begin
      full_adder full_adder_inst(
        .A(A[i]),
        .B(B[i]),
        .C_in(carry[i]),
        .S(sum[i]),
        .C_out(carry[i+1])
      );
    end
  endgenerate

  assign carry[0] = 0;

  always @* begin
    S = sum[3:0];
    C_out = carry[4];
  end

