module full_adder(a, b, cin, sum, cout);
    input a, b, cin;
    output sum, cout;

    // XOR gate for sum
    assign sum = a ^ b ^ cin;

    // AND gate for carry-out
    assign cout = (a & b) | (a & cin) | (b & cin);
endmodule

