module traffic_light_controller (
  input clk,
  input reset,
  output reg red,
  output reg yellow,
  output reg green
);

  reg [3:0] state;

  always @(posedge clk) begin
    if (reset) begin
      state <= 4'b0000;
      red <= 1'b0;
      yellow <= 1'b0;
      green <= 1'b0;
    end
    else begin
      case (state)
        4'b0000: begin // Green light on for 10 clock cycles
          green <= 1'b1;
          yellow <= 1'b0;
          red <= 1'b0;
          state <= 4'b0001;
        end
        4'b0001: begin // Yellow light on for 2 clock cycles
          green <= 1'b0;
          yellow <= 1'b1;
          red <= 1'b0;
          state <= 4'b0010;
        end
        4'b0010: begin // Red light on for 8 clock cycles
          green <= 1'b0;
          yellow <= 1'b0;
          red <= 1'b1;
          state <= 4'b0011;
        end
        4'b0011: begin // Yellow light on for 2 clock cycles
          green <= 1'b0;
          yellow <= 1'b1;
          red <= 1'b0;
          state <= 4'b0000;
        end
      endcase
    end
  end

endmodule

