    parameter PC_RESET = 32'h0000_0000;
    parameter FROM_INC4 = 2'b00;
    parameter FROM_OPCODE25_0 = 2'b01;
    parameter FROM_BRANCH = 2'b10;
    parameter FROM_LBRANCH = 2'b11;

