      parity_out <= parity_bit;
    end else begin
      parity_out <= ~parity_bit;
    end
  end

  always @(*) begin
    count = data_in[0] + data_in[1] + data_in[2] + data_in[3] + data_in[4] + data_in[5] + data_in[6] + data_in[7] + parity_in;

    if (parity_type == "even") begin
      correct <= (count % 2 == 0);
    end else begin
      correct <= (count % 2 == 1);
    end
  end

endmodule

